describe('Payment Flow', () => {
    beforeEach(() => {
        cy.visit('/payment'); // Adjust the URL as necessary
    });

    it('should display loading state while payment is processing', () => {
        cy.get('input[name="cardNumber"]').type('4111111111111111');
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvc"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.get('.loading-spinner').should('be.visible');
        cy.get('.payment-success').should('not.exist');
        cy.get('.payment-error').should('not.exist');

        // Simulate payment processing time
        cy.wait(3000); // Adjust wait time as necessary

        cy.get('.loading-spinner').should('not.exist');
        cy.get('.payment-success').should('be.visible');
    });

    it('should handle payment failure and display error message', () => {
        cy.get('input[name="cardNumber"]').type('4000000000000002'); // Test card that simulates failure
        cy.get('input[name="expiryDate"]').type('12/25');
        cy.get('input[name="cvc"]').type('123');
        cy.get('button[type="submit"]').click();

        cy.get('.loading-spinner').should('be.visible');
        cy.get('.payment-success').should('not.exist');
        cy.get('.payment-error').should('not.exist');

        // Simulate payment processing time
        cy.wait(3000); // Adjust wait time as necessary

        cy.get('.loading-spinner').should('not.exist');
        cy.get('.payment-error').should('be.visible').and('contain', 'Payment failed. Please try again.');
    });
});
